import{_ as s,o as a,c as t,ag as i}from"./chunks/framework.B7PviQjB.js";const k=JSON.parse('{"title":"Optional features","description":"Turn on share-link analytics, database and lakehouse connections, error tracking, webhooks, and the public template gallery on a self-hosted Wafflebase.","frontmatter":{"title":"Optional features","description":"Turn on share-link analytics, database and lakehouse connections, error tracking, webhooks, and the public template gallery on a self-hosted Wafflebase.","type":"how-to"},"headers":[],"relativePath":"developers/self-hosting/optional-features.md","filePath":"developers/self-hosting/optional-features.md"}'),n={name:"developers/self-hosting/optional-features.md"};function l(o,e,h,p,r,d){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="optional-features" tabindex="-1">Optional features <a class="header-anchor" href="#optional-features" aria-label="Permalink to &quot;Optional features&quot;">​</a></h1><p>Turn on the parts of Wafflebase that stay off until you configure them: share-link analytics, database and lakehouse connections, error tracking, webhooks, and the public template gallery.</p><p>Each feature is independent. Leaving one off does not affect the rest of the app.</p><h2 id="turn-on-share-link-analytics" tabindex="-1">Turn on share-link analytics <a class="header-anchor" href="#turn-on-share-link-analytics" aria-label="Permalink to &quot;Turn on share-link analytics&quot;">​</a></h2><p>Share-link analytics records views, unique and returning visitors, and time spent for documents opened through a share link. It runs on Kafka and StarRocks.</p><ol><li><p>Start Kafka and StarRocks. Locally, use the Compose profile:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> analytics</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>This starts <code>kafka</code> (<code>29092</code>) and <code>starrocks</code> (<code>8030</code>, <code>9030</code>, <code>8040</code>), and creates the topic, table, and load job.</p></li><li><p>Point the backend at them:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WAFFLEBASE_KAFKA_ADDRESSES=localhost:29092</span></span>
<span class="line"><span>WAFFLEBASE_KAFKA_TOPIC=wafflebase-view-events</span></span>
<span class="line"><span>WAFFLEBASE_STARROCKS_DSN=root:@tcp(localhost:9030)/wafflebase</span></span></code></pre></div></li><li><p>Restart the backend.</p></li><li><p>Open a document through a share link to record a view.</p></li></ol><p>An <strong>Analytics</strong> entry appears in the workspace sidebar, at <code>/w/&lt;workspaceId&gt;/analytics</code>. Document managers also see per-document analytics. Leave the variables unset until the services run; pointing at brokers that are down only produces connection errors.</p><h2 id="connect-databases-and-lakehouse-tables" tabindex="-1">Connect databases and lakehouse tables <a class="header-anchor" href="#connect-databases-and-lakehouse-tables" aria-label="Permalink to &quot;Connect databases and lakehouse tables&quot;">​</a></h2><p>Sheets can read from external databases and from Iceberg and Delta tables. See <a href="/docs/sheets/connect-a-database.html">Connect a database</a> and <a href="/docs/sheets/lakehouse.html">Lakehouse</a> for the user side.</p><ol><li><p>Generate an encryption key for stored credentials and set it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rand</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -hex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span></span></code></pre></div><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DATASOURCE_ENCRYPTION_KEY=&lt;the 64 hex characters&gt;</span></span></code></pre></div></li><li><p>To use a custom S3, Azure, or GCS endpoint or an Iceberg REST catalog, list each exact origin:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LAKEHOUSE_ALLOWED_ENDPOINTS=https://s3.example.com,https://catalog.example.com</span></span></code></pre></div></li><li><p>Optional: to let lakehouse tables read the server&#39;s own disk, set <code>LAKEHOUSE_ALLOW_LOCAL_PATHS=true</code> and <code>LAKEHOUSE_LOCAL_ROOT</code> to the only directory they may use.</p></li><li><p>Restart the backend.</p></li></ol><p>Keep <code>DATASOURCE_ENCRYPTION_KEY</code> safe and stable; changing it makes stored credentials unreadable. Tune query limits with the <code>LAKEHOUSE_*</code> variables in <a href="/docs/developers/self-hosting/configuration.html#backend-datasources-and-lakehouse">Configuration</a>.</p><h3 id="run-the-lakehouse-without-internet-access" tabindex="-1">Run the lakehouse without internet access <a class="header-anchor" href="#run-the-lakehouse-without-internet-access" aria-label="Permalink to &quot;Run the lakehouse without internet access&quot;">​</a></h3><p>The lakehouse needs the DuckDB extensions <code>httpfs</code>, <code>iceberg</code>, <code>delta</code>, <code>azure</code>, and <code>avro</code>. The production image already contains them (about 170 MB). Outside the image, DuckDB downloads a missing extension from <code>extensions.duckdb.org</code> on first use.</p><ol><li>If the server cannot reach the internet and you do not use the image, copy the extensions into a directory on the server.</li><li>Set <code>LAKEHOUSE_DUCKDB_EXTENSION_DIR</code> to that directory.</li></ol><h2 id="report-errors-to-sentry" tabindex="-1">Report errors to Sentry <a class="header-anchor" href="#report-errors-to-sentry" aria-label="Permalink to &quot;Report errors to Sentry&quot;">​</a></h2><p>Error tracking sends backend and browser errors to a Sentry project you own. It is off until you set a DSN.</p><ol><li><p>Create a Sentry project for the backend and one for the frontend.</p></li><li><p>Set the backend DSN and restart:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SENTRY_DSN=https://&lt;key&gt;@&lt;org&gt;.ingest.sentry.io/&lt;project&gt;</span></span></code></pre></div></li><li><p>Build the frontend with the browser DSN:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VITE_SENTRY_DSN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">org</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.ingest.sentry.io/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">project</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div></li><li><p>Optional: to upload source maps, also set <code>SENTRY_AUTH_TOKEN</code>, <code>SENTRY_ORG</code>, and <code>SENTRY_PROJECT</code> in the build environment. The build uploads the maps and removes them from <code>dist</code>.</p></li></ol><p>Traces are sampled at 10% by default. Change it with <code>SENTRY_TRACES_SAMPLE_RATE</code> and <code>VITE_SENTRY_TRACES_SAMPLE_RATE</code>. No session replays are recorded.</p><h2 id="turn-on-webhooks" tabindex="-1">Turn on webhooks <a class="header-anchor" href="#turn-on-webhooks" aria-label="Permalink to &quot;Turn on webhooks&quot;">​</a></h2><p>Webhooks let workspace owners send signed events to n8n, Zapier, or their own servers. See <a href="/docs/developers/webhooks.html">Webhooks</a> for the owner side.</p><ol><li><p>Set an encryption key for signing secrets. If <code>DATASOURCE_ENCRYPTION_KEY</code> is already set, it is used and you can skip this step.</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WAFFLEBASE_SECRETS_ENCRYPTION_KEY=&lt;64 hex characters from openssl rand -hex 32&gt;</span></span></code></pre></div></li><li><p>Turn webhooks on and restart the backend:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WAFFLEBASE_WEBHOOKS_ENABLED=true</span></span></code></pre></div></li><li><p>Optional: let webhooks reach a service on your own network, such as an n8n at <code>10.0.4.12</code>. Webhooks refuse private addresses and <code>http://</code> unless you allow them:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WAFFLEBASE_WEBHOOK_ALLOWED_CIDRS=10.0.4.0/24</span></span>
<span class="line"><span>WAFFLEBASE_WEBHOOK_ALLOW_HTTP=true</span></span></code></pre></div></li></ol><p>Every backend replica sends deliveries; they share the work through the database, so you do not need a separate worker. Without a key, the boot log says <code>webhooks are enabled but unusable</code> and creating a webhook fails with the same reason.</p><h2 id="open-the-public-template-gallery" tabindex="-1">Open the public template gallery <a class="header-anchor" href="#open-the-public-template-gallery" aria-label="Permalink to &quot;Open the public template gallery&quot;">​</a></h2><p>Workspace and link-only templates work without setup. The public gallery, where anyone on your instance can browse approved templates, needs reviewers and enforced access control. See <a href="/docs/collaborate/templates.html">Templates</a> for the user side.</p><ol><li><p>Turn on access control and confirm it is enforcing. See <a href="/docs/developers/self-hosting/deploy.html#turn-on-per-document-access-control">Turn on per-document access control</a>.</p></li><li><p>Set <code>YORKIE_AUTH_WEBHOOK_ENFORCE=true</code>. The gallery requires this exact value; unset is not enough.</p></li><li><p>Find the user IDs of your reviewers:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id, email </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;User&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div></li><li><p>Set them and restart the backend:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WAFFLEBASE_TEMPLATE_REVIEWER_IDS=1,7</span></span></code></pre></div></li></ol><p>Reviewers decide submissions at <code>/admin/templates</code> and are notified when one arrives. Until both settings hold, publishers cannot submit to the public gallery.</p><h3 id="seed-the-gallery-with-starter-templates" tabindex="-1">Seed the gallery with starter templates <a class="header-anchor" href="#seed-the-gallery-with-starter-templates" aria-label="Permalink to &quot;Seed the gallery with starter templates&quot;">​</a></h3><ol><li><p>Create the starter documents in a workspace, as a user who is also a reviewer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> seed:templates:build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">workspaceI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --author</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">userI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div></li><li><p>Install Chromium for the registration step:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @wafflebase/frontend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chromium</span></span></code></pre></div></li><li><p>With the frontend and backend running, publish, submit, and approve each one:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> register:templates:build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --author</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">userI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frontend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://app.example.com</span></span></code></pre></div></li></ol><p>The second command skips documents that already have a listing. Add <code>--reset</code> to unpublish and publish them again.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/developers/self-hosting/configuration.html">Configuration</a> for every variable these features read.</li><li><a href="/docs/developers/self-hosting/deploy.html">Deploy to production</a> for access control and storage.</li><li><a href="/docs/developers/self-hosting/troubleshooting.html">Troubleshooting</a> if a feature fails after you turn it on.</li></ul>`,31)])])}const u=s(n,[["render",l]]);export{k as __pageData,u as default};
